// ************
// Types
// ************

import '@dev.hiconic/gm_root-model';
import '@dev.hiconic/gm_i18n-model';
import '@dev.hiconic/gm_manipulation-model';
import '@dev.hiconic/gm_meta-model';
import '@dev.hiconic/gm_gm-core-api';

import { T } from '@dev.hiconic/hc-js-base';

export declare namespace meta {
	const groupId: string;
	const artifactId: string;
	const version: string;
}

export import AsyncEvaluation = T.com.braintribe.model.template.meta.AsyncEvaluation;
export import DynamicPropertyMetaDataAssignment = T.com.braintribe.model.template.meta.DynamicPropertyMetaDataAssignment;
export import DynamicTypeMetaDataAssignment = T.com.braintribe.model.template.meta.DynamicTypeMetaDataAssignment;
export import ForceForm = T.com.braintribe.model.template.meta.ForceForm;
export import Presentation = T.com.braintribe.model.template.meta.Presentation;
export import ResolveVariables = T.com.braintribe.model.template.vd.ResolveVariables;
export import StringRepresentation = T.com.braintribe.model.template.meta.StringRepresentation;
export import Template = T.com.braintribe.model.template.Template;
export import TemplateBase = T.com.braintribe.model.template.TemplateBase;
export import TemplateMetaData = T.com.braintribe.model.template.meta.TemplateMetaData;
export import VariablePresentation = T.com.braintribe.model.template.meta.VariablePresentation;
export import VariableSequence = T.com.braintribe.model.template.meta.VariableSequence;

declare module '@dev.hiconic/hc-js-base' {

	namespace T.com.braintribe.model.template {

		const Template: hc.reflection.EntityType<Template>;
		type Template = T.com.braintribe.model.generic.GenericEntity &
		  Entity<"com.braintribe.model.template.Template", {
			description: T.com.braintribe.model.generic.i18n.LocalizedString;
			metaData: set<T.com.braintribe.model.template.meta.TemplateMetaData>;
			name: T.com.braintribe.model.generic.i18n.LocalizedString;
			prototype_: Base;
			prototypeTypeSignature: string;
			script: T.com.braintribe.model.generic.manipulation.Manipulation;
			technicalName: string;
		}>;

		const TemplateBase: hc.reflection.EntityType<TemplateBase>;
		type TemplateBase = T.com.braintribe.model.meta.GmEntityType &
		  Entity<"com.braintribe.model.template.TemplateBase">;

	}

	namespace T.com.braintribe.model.template.meta {

		const AsyncEvaluation: hc.reflection.EntityType<AsyncEvaluation>;
		type AsyncEvaluation = TemplateMetaData &
		  Entity<"com.braintribe.model.template.meta.AsyncEvaluation">;

		const DynamicPropertyMetaDataAssignment: hc.reflection.EntityType<DynamicPropertyMetaDataAssignment>;
		type DynamicPropertyMetaDataAssignment = VariablePresentation &
		  Entity<"com.braintribe.model.template.meta.DynamicPropertyMetaDataAssignment", {
			metaData: set<T.com.braintribe.model.meta.data.MetaData>;
			variable: T.com.braintribe.model.generic.value.Variable;
		}>;

		const DynamicTypeMetaDataAssignment: hc.reflection.EntityType<DynamicTypeMetaDataAssignment>;
		type DynamicTypeMetaDataAssignment = Presentation &
		  Entity<"com.braintribe.model.template.meta.DynamicTypeMetaDataAssignment", {
			metaData: set<T.com.braintribe.model.meta.data.MetaData>;
		}>;

		const ForceForm: hc.reflection.EntityType<ForceForm>;
		type ForceForm = Presentation &
		  Entity<"com.braintribe.model.template.meta.ForceForm", {
			enabled: P<boolean, { nullable: false }>;
		}>;

		const Presentation: hc.reflection.EntityType<Presentation>;
		type Presentation = TemplateMetaData &
		  Entity<"com.braintribe.model.template.meta.Presentation">;

		const StringRepresentation: hc.reflection.EntityType<StringRepresentation>;
		type StringRepresentation = TemplateMetaData &
		  Entity<"com.braintribe.model.template.meta.StringRepresentation", {
			value: string;
		}>;

		const TemplateMetaData: hc.reflection.EntityType<TemplateMetaData>;
		type TemplateMetaData = T.com.braintribe.model.generic.GenericEntity &
		  Entity<"com.braintribe.model.template.meta.TemplateMetaData">;

		const VariablePresentation: hc.reflection.EntityType<VariablePresentation>;
		type VariablePresentation = Presentation &
		  Entity<"com.braintribe.model.template.meta.VariablePresentation">;

		const VariableSequence: hc.reflection.EntityType<VariableSequence>;
		type VariableSequence = VariablePresentation &
		  Entity<"com.braintribe.model.template.meta.VariableSequence", {
			variables: list<T.com.braintribe.model.generic.value.Variable>;
		}>;

	}

	namespace T.com.braintribe.model.template.vd {

		const ResolveVariables: hc.reflection.EntityType<ResolveVariables>;
		type ResolveVariables = T.com.braintribe.model.generic.value.type.ImplicitlyTypedDescriptor &
		  Entity<"com.braintribe.model.template.vd.ResolveVariables", {
			value: Base;
		}>;

	}

}
